function GitDigest($rel){$s=[Diagnostics.ProcessStartInfo]::new('git');$s.WorkingDirectory=$root;$s.UseShellExecute=$false;$s.RedirectStandardOutput=$true;$s.RedirectStandardError=$true;foreach($arg in @('cat-file','blob',($parent+':'+$rel))){$s.ArgumentList.Add($arg)};$p=[Diagnostics.Process]::Start($s);$d=[Security.Cryptography.SHA256]::Create();try{$hash=$d.ComputeHash($p.StandardOutput.BaseStream);$err=$p.StandardError.ReadToEnd();$p.WaitForExit();if($p.ExitCode -ne 0){throw $err};[Convert]::ToHexString($hash).ToLowerInvariant()}finally{$d.Dispose();$p.Dispose()}}
